package importer

import (
	"context"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/stefanluchs/my-velo/internal/store"
)

// TestRealData imports personal FIT files that must never be committed.
// Run it with a local folder or Garmin export:
//
//	MYVELO_REAL_DATA=/tmp/myvelo-inbox go test -run TestRealData -v ./internal/importer
func TestRealData(t *testing.T) {
	root := os.Getenv("MYVELO_REAL_DATA")
	if root == "" {
		t.Skip("set MYVELO_REAL_DATA to a folder or ZIP with FIT files")
	}
	ctx := context.Background()
	s, err := store.Open(ctx, filepath.Join(t.TempDir(), "real.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()
	im := &Importer{Store: s, RawDir: filepath.Join(t.TempDir(), "raw")}

	var rawBytes, streamBytes, records, trackPoints int
	start := time.Now()
	stats, err := im.ImportPath(ctx, root, func(r Result) {
		if r.Status == StatusFailed {
			t.Logf("failed: %s: %s", r.Origin, r.Error)
			return
		}
		blob, _ := s.Stream(ctx, r.ActivityID)
		streamBytes += len(blob.Data)
		if st, err := DecodeStream(blob); err == nil {
			records += st.Len()
		}
		if tr, err := s.Track(ctx, r.ActivityID); err == nil {
			trackPoints += tr.Points
		}
	})
	if err != nil {
		t.Fatal(err)
	}
	elapsed := time.Since(start)
	_ = filepath.Walk(im.RawDir, func(_ string, fi os.FileInfo, _ error) error {
		if fi != nil && !fi.IsDir() {
			rawBytes += int(fi.Size())
		}
		return nil
	})

	t.Logf("stats %+v in %v (%.0f ms/file)", stats, elapsed.Round(time.Millisecond), float64(elapsed.Milliseconds())/float64(max(stats.Total(), 1)))
	t.Logf("raw %d KB, streams %d KB (%.0f%%), records %d, track points %d (%.1f%% of records)",
		rawBytes/1024, streamBytes/1024, 100*float64(streamBytes)/float64(max(rawBytes, 1)),
		records, trackPoints, 100*float64(trackPoints)/float64(max(records, 1)))

	again, err := im.ImportPath(ctx, root, nil)
	if err != nil {
		t.Fatal(err)
	}
	if again.Created != 0 || again.Updated != 0 {
		t.Errorf("re-import not idempotent: %+v", again)
	}
}
